static char* extract_next_array_token(char** p) {
    char* s = *p;
    while (*s && *s != '[') s++;
    if (!*s) return NULL;
    char* start = s++;
    int depth = 1;
    while (*s && depth) {
        if (*s == '[') depth++;
        else if (*s == ']') depth--;
        s++;
    }
    size_t len = s - start;
    char* out = malloc(len + 1);
    strncpy(out, start, len);
    out[len] = '\0';
    *p = s;
    return out;
}

static int* parse_int_array_from_token(const char* token, int* out_size) {
    // token is like [1,2,3]
    if (!token) { *out_size = 0; return NULL; }
    if (strcmp(token, "[]") == 0) { *out_size = 0; return NULL; }
    const char* p = token + 1; // skip [
    int capacity = 16; int count = 0;
    int* arr = malloc(capacity * sizeof(int));
    while (*p && *p != ']') {
        while (*p == ' ' || *p == ',') p++;
        if (*p == ']') break;
        int val = strtol(p, (char**)&p, 10);
        if (count >= capacity) { capacity *= 2; arr = realloc(arr, capacity * sizeof(int)); }
        arr[count++] = val;
        while (*p == ' ' || *p == ',') p++;
    }
    *out_size = count;
    return arr;
}

