import java.util.*;
import java.io.*;

class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

class Solution {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        ListNode l1 = list1, l2 = list2;
        while (l1 != null && l2 != null) {
            if (l1.val <= l2.val) {
                cur.next = l1; l1 = l1.next;
            } else {
                cur.next = l2; l2 = l2.next;
            }
            cur = cur.next;
        }
        cur.next = (l1 != null) ? l1 : l2;
        return dummy.next;
    }
}

public class Main {
    private static int[] parseIntArray(String token) {
        token = token.trim();
        if (token.equals("[]")) return new int[0];
        token = token.substring(1, token.length() - 1).trim();
        if (token.isEmpty()) return new int[0];
        String[] parts = token.split(",");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; ++i) arr[i] = Integer.parseInt(parts[i].trim());
        return arr;
    }
    private static ListNode fromArray(int[] arr) {
        if (arr.length == 0) return null;
        ListNode head = new ListNode(arr[0]); ListNode cur = head;
        for (int i = 1; i < arr.length; ++i) { cur.next = new ListNode(arr[i]); cur = cur.next; }
        return head;
    }
    private static String toJsonArray(ListNode head) {
        StringBuilder sb = new StringBuilder(); sb.append("[");
        boolean first = true; while (head != null) { if (!first) sb.append(","); sb.append(head.val); first = false; head = head.next; }
        sb.append("]"); return sb.toString();
    }
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        // Extract two top-level arrays
        int first = line.indexOf('[');
        int second = line.indexOf(']', first) + 1;
        String token1 = line.substring(first, second);
        int third = line.indexOf('[', second);
        int fourth = line.indexOf(']', third) + 1;
        String token2 = line.substring(third, fourth);
        int[] a1 = parseIntArray(token1);
        int[] a2 = parseIntArray(token2);
        ListNode l1 = fromArray(a1);
        ListNode l2 = fromArray(a2);
        ListNode res = new Solution().mergeTwoLists(l1, l2);
        System.out.println(toJsonArray(res));
    }
}

