import sys, json
from typing import List, Optional

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next
    @staticmethod
    def from_list(lst: List[int]) -> Optional['ListNode']:
        if not lst: return None
        head = ListNode(lst[0]); cur = head
        for v in lst[1:]:
            cur.next = ListNode(v); cur = cur.next
        return head
    def to_list(self) -> List[int]:
        out = []
        cur = self
        while cur:
            out.append(cur.val); cur = cur.next
        return out

class Solution:
    def mergeTwoLists(self, list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:
        # Iterative dummy-node solution
        dummy = ListNode(0)
        cur = dummy
        l1, l2 = list1, list2
        while l1 and l2:
            if l1.val <= l2.val:
                cur.next = l1
                l1 = l1.next
            else:
                cur.next = l2
                l2 = l2.next
            cur = cur.next
        cur.next = l1 or l2
        return dummy.next

if __name__ == '__main__':
    args = json.loads(sys.stdin.readline())
    l1 = ListNode.from_list(args[0])
    l2 = ListNode.from_list(args[1])
    res = Solution().mergeTwoLists(l1, l2)
    out = res.to_list() if res else []
    print(json.dumps(out))

